{"content": "    80|.mc{position:relative;z-index:2;background:none;border:1px solid rgba(255,255,255,0.08);font-size:1.3rem;cursor:pointer;color:rgba(210,195,235,0.4);padding:2px 10px;border-radius:50%}
    81|.mc:hover{color:var(--pink);border-color:var(--pink)}
    82|.mb{padding:18px 22px}
    83|.mb section{margin-bottom:16px}
    84|.mb section h3{font-size:1rem;background:linear-gradient(135deg,#ff6b9d,#c471f5);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;margin-bottom:8px;padding-bottom:4px;border-bottom:2px solid rgba(255,107,157,0.1)}
