    87|.mi-item strong{color:var(--pink)}
    88|.ch{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}
    89|.ch-card{display:flex;gap:10px;background:var(--ch-card-bg);padding:10px;border-radius:8px;border:1px solid rgba(255,107,157,0.04);transition:all 0.2s}
    90|.ch-card:hover{background:rgba(196,113,245,0.06)}
    91|.ch-av{width:52px;height:52px;border-radius:50%;background:linear-gradient(135deg,#c471f5,#ff6b9d);display:flex;align-items:center;justify-content:center;font-size:1.3rem;flex-shrink:0}
    92|.ch-info h4{font-size:0.83rem;color:#f0e8ff}
