    94|.ch-info p{font-size:0.72rem;color:var(--muted);line-height:1.3}
    95|.cg{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:8px}
    96|.cg-i{border-radius:8px;overflow:hidden;border:1.5px solid rgba(126,200,227,0.08);aspect-ratio:16/10;transition:all 0.3s;cursor:pointer}
    97|.cg-i img{width:100%;height:100%;object-fit:cover}
    98|.cg-i:hover{transform:scale(1.04);border-color:rgba(196,113,245,0.35);box-shadow:0 3px 10px rgba(196,113,245,0.12)}
    99|.cg-i .ph{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:2rem;background:linear-gradient(135deg,rgba(196,113,245,0.08),rgba(126,200,227,0.08))}
   100|.rl{display:flex;flex-wrap:wrap;gap:6px}
   101|.rlink{display:inline-flex;align-items:center;gap:3px;padding:7px 13px;border-radius:18px;text-decoration:none;font-size:0.78rem;font-weight:600;transition:all 0.3s}
