   118|.music-bar{position:fixed;bottom:0;left:0;right:0;z-index:300;background:var(--music-bg);backdrop-filter:blur(14px);border-top:1px solid rgba(255,107,157,0.08);padding:8px 14px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:center}
   119|.music-bar .mtitle{font-size:0.76rem;color:var(--muted);max-width:240px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
   120|.music-bar .mdots{display:flex;gap:4px}
   121|.music-bar .mdot{width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,0.18);cursor:pointer;transition:all 0.3s}
   122|.music-bar .mdot.on{background:var(--pink);box-shadow:0 0 8px rgba(255,107,157,0.5)}
   123|.mbtn{width:30px;height:30px;border-radius:50%;border:1px solid rgba(255,255,255,0.08);background:rgba(255,255,255,0.03);color:#c8b8e0;cursor:pointer;font-size:0.75rem;display:flex;align-items:center;justify-content:center;transition:all 0.3s;flex-shrink:0}
   124|.mbtn:hover{background:rgba(196,113,245,0.15);border-color:var(--purple)}
   125|.mbtn.play{width:36px;height:36px;background:linear-gradient(135deg,#ff6b9d,#c471f5);border:none;color:#fff;font-size:0.95rem}
   126|.mbtn.play.on{animation:mp 2s infinite}
   127|@keyframes mp{0%,100%{box-shadow:0 0 5px rgba(255,107,157,0.25)}50%{box-shadow:0 0 16px rgba(255,107,157,0.55)}}
   128|.qnav{position:fixed;bottom:55px;right:14px;z-index:150;display:flex;flex-direction:column;gap:5px}
   129|.qbtn{width:38px;height:38px;border-radius:50%;border:1px solid rgba(196,113,245,0.12);background:rgba(14,8,28,0.85);backdrop-filter:blur(6px);color:#c8b8e0;font-size:0.95rem;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all 0.3s}
   130|.qbtn:hover{background:rgba(196,113,245,0.15);border-color:var(--purple);transform:scale(1.06)}
   131|footer{text-align:center;padding:18px;color:var(--footer-color);font-size:0.72rem;position:relative;z-index:1;margin-bottom:48px}
   132|footer .h{color:var(--pink)}
   133|/* Message Board */
   134|.msg-board{max-width:800px;margin:0 auto 60px;padding:0 20px}
   135|.msg-form{display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap}
   136|.msg-name{width:100px;padding:8px 12px;border:1.5px solid rgba(255,107,157,0.15);border-radius:20px;font-size:0.8rem;background:var(--input-bg);color:var(--text);outline:none}
   137|.msg-text{flex:1;min-width:150px;padding:8px 12px;border:1.5px solid rgba(255,107,157,0.15);border-radius:20px;font-size:0.8rem;background:var(--input-bg);color:var(--text);outline:none}
   138|.msg-name:focus,.msg-text:focus{border-color:var(--pink)}
   139|.msg-list{display:flex;flex-direction:column;gap:8px}
   140|.msg-item{background:var(--card-bg);backdrop-filter:blur(8px);border:1px solid var(--card-bd);border-radius:12px;padding:10px 14px;font-size:0.8rem}
   141|.msg-item .m-n{color:var(--pink);font-weight:700;margin-right:8px}
