   143|.msg-item .m-time{font-size:0.65rem;color:rgba(160,140,200,0.4);float:right;margin-top:2px}
   144|.no-r{text-align:center;padding:50px 20px;color:var(--muted)}
   145|.no-r .ic{font-size:3rem;margin-bottom:6px}
   146|@media(max-width:768px){.games-grid{grid-template-columns:repeat(2,1fr)}.ch{grid-template-columns:1fr}.cg{grid-template-columns:repeat(2,1fr)}.rs-grid{grid-template-columns:1fr}}
   147|@media(max-width:480px){.games-grid{grid-template-columns:1fr}}
